import{_ as e,o as a,c as r,a2 as l}from"./chunks/framework.CiKk3sJz.js";const k=JSON.parse('{"title":"漫画 · 第 39 话 color-mix 与 light-dark：浏览器原生调色盘","description":"","frontmatter":{},"headers":[],"relativePath":"comics/css/EP.39-color-mix-light-dark.md","filePath":"comics/css/EP.39-color-mix-light-dark.md","lastUpdated":1792579602000}'),c={name:"comics/css/EP.39-color-mix-light-dark.md"};function d(t,o,i,h,s,n){return a(),r("div",null,[...o[0]||(o[0]=[l('<h1 id="漫画-·-第-39-话-color-mix-与-light-dark-浏览器原生调色盘" tabindex="-1">漫画 · 第 39 话 color-mix 与 light-dark：浏览器原生调色盘 <a class="header-anchor" href="#漫画-·-第-39-话-color-mix-与-light-dark-浏览器原生调色盘" aria-label="Permalink to &quot;漫画 · 第 39 话 color-mix 与 light-dark：浏览器原生调色盘&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../../docs/css/25-color-mix-light-dark">docs/css/25-color-mix-light-dark.md</a> ｜ 原画：<a href="./EP.39-color-mix-light-dark.svg">EP.39-color-mix-light-dark.svg</a></p></blockquote><h2 id="登场角色" tabindex="-1">登场角色 <a class="header-anchor" href="#登场角色" aria-label="Permalink to &quot;登场角色&quot;">​</a></h2><ul><li><strong>像素酱</strong>：CSS 造型师，本话主角。Sass 变量 <code>$light10: lighten($brand, 10%)</code> 写了 10 级色阶，暗色模式又复制 200 行媒体查询覆盖，换品牌色要重新编译整套，表单控件在暗色下突兀发白。</li><li><strong>标签君</strong>：HTML5 结构师，搬出三把原生钥匙——<code>color-mix()</code> 浏览器端混色、<code>light-dark()</code> 单声明双色、<code>color-scheme</code> 让原生控件自动适配。</li></ul><h2 id="剧情梗概" tabindex="-1">剧情梗概 <a class="header-anchor" href="#剧情梗概" aria-label="Permalink to &quot;剧情梗概&quot;">​</a></h2><p>像素酱被「调色靠编译、暗色靠覆盖」折磨：预处理器生成的色阶是死值，运行时改品牌色完全做不到；媒体查询写两套颜色，代码量翻倍还容易漏。标签君引入 <code>color-mix(in oklch, var(--brand), white 20%)</code>——一个变量实时派生整套色阶；<code>light-dark(#fff, #0b1220)</code> 一句替代整段媒体查询；<code>:root { color-scheme: light dark }</code> 连滚动条和表单控件都自动换装。像素酱发现 JS 只改一个 <code>--brand</code>，全站色阶实时更新。</p><h2 id="分格解读" tabindex="-1">分格解读 <a class="header-anchor" href="#分格解读" aria-label="Permalink to &quot;分格解读&quot;">​</a></h2><h3 id="格1-·-痛点现场" tabindex="-1">格1 · 痛点现场 <a class="header-anchor" href="#格1-·-痛点现场" aria-label="Permalink to &quot;格1 · 痛点现场&quot;">​</a></h3><p>传统方案依赖预处理器：<code>lighten()</code>/<code>darken()</code> 在编译期算死，浏览器端无法动态调整；暗色模式靠 <code>prefers-color-scheme</code> 媒体查询逐条覆盖，200 行变量写两遍。叠加痛苦：编译依赖、控件突兀、JS 切 class 闪屏、动态主题完全做不到。</p><h3 id="格2-·-机制登场" tabindex="-1">格2 · 机制登场 <a class="header-anchor" href="#格2-·-机制登场" aria-label="Permalink to &quot;格2 · 机制登场&quot;">​</a></h3><p><code>color-mix(in oklch, #7c3aed, white 20%)</code> 在指定色彩空间按比例混色，oklch 感知最均匀；<code>light-dark(#fff, #0b1220)</code> 根据系统偏好自动二选一，但<strong>必须</strong>配合 <code>color-scheme: light dark</code> 声明，否则永远返回亮色值。</p><h3 id="格3-·-落地收束" tabindex="-1">格3 · 落地收束 <a class="header-anchor" href="#格3-·-落地收束" aria-label="Permalink to &quot;格3 · 落地收束&quot;">​</a></h3><p>四大场景：品牌色阶生成（一个变量派生 10 级）、暗色模式（代码量减半）、控件适配（滚动条/表单/选中色自动换装）、动态主题（JS 改一个变量全站联动）。记住边界：<strong>srgb 混合可能发灰</strong>，追求感知均匀一律用 oklch。</p><h2 id="码叔划重点" tabindex="-1">码叔划重点 <a class="header-anchor" href="#码叔划重点" aria-label="Permalink to &quot;码叔划重点&quot;">​</a></h2><ol><li>color-mix(in oklch, ...) 感知最均匀；srgb 混合可能产生 muddy 中间色。</li><li>light-dark() 需配合 color-scheme: light dark，否则永远返回亮色值。</li><li>:root { color-scheme: light dark } 让滚动条/表单控件自动适配暗色。</li></ol><h2 id="自测一题" tabindex="-1">自测一题 <a class="header-anchor" href="#自测一题" aria-label="Permalink to &quot;自测一题&quot;">​</a></h2><p><strong>问</strong>：为什么 <code>light-dark()</code> 单独使用时永远返回第一个颜色（亮色值）？</p><p><strong>答</strong>：<code>light-dark()</code> 的判定依据是元素计算后的 <code>color-scheme</code> 值，而不是系统偏好本身。若未在 <code>:root</code> 或祖先声明 <code>color-scheme: light dark</code>，元素只支持 light 方案，<code>light-dark()</code> 自然永远选亮色。正确姿势：<code>:root { color-scheme: light dark }</code> 声明双支持，函数才会响应系统暗色偏好。</p><h2 id="动手实验" tabindex="-1">动手实验 <a class="header-anchor" href="#动手实验" aria-label="Permalink to &quot;动手实验&quot;">​</a></h2><ul><li>四色彩空间混合对比 + light-dark 主题卡片 + color-scheme 原生控件 + 品牌色 5 级变体：<a href="./../../examples/css/25-color-mix-light-dark/index-01-color-mix-light-dark.html">examples/css/25-color-mix-light-dark/</a></li></ul><h2 id="下一话预告" tabindex="-1">下一话预告 <a class="header-anchor" href="#下一话预告" aria-label="Permalink to &quot;下一话预告&quot;">​</a></h2><p>第 40 话《details 与 summary 进阶》——<code>name</code> 属性互斥手风琴零 JS、<code>::details-content</code> 高度平滑动画、<code>interpolate-size: allow-keywords</code> 解锁 auto 过渡，原生折叠面板让 15KB 组件库退役。</p>',22)])])}const g=e(c,[["render",d]]);export{k as __pageData,g as default};
